<template>
  <div class="page-head"><div><h2>设备与位置</h2><span class="muted">管理工程机械主数据、最近位置快照与历史水害关联</span></div><n-space><n-select v-model:value="projectId" :options="projectOptions" clearable placeholder="全部施工项目" style="width:240px" @update:value="loadEquipment"/><n-button @click="loadEquipment">刷新</n-button><n-button type="primary" @click="newEquipment">新增工程机械</n-button></n-space></div>
  <n-alert type="info" style="margin-bottom:14px">设备位置均为人工录入或CSV导入的时间点快照，不代表设备实时位置、运行状态或运动轨迹。</n-alert>
  <n-card>
    <div class="table-actions"><span>共 {{rows.length}} 台设备</span><label class="csv-button"><input type="file" accept=".csv,text/csv" @change="importCsv">导入位置CSV</label></div>
    <n-alert v-if="importResult" :type="importResult.failed_count?'warning':'success'" style="margin-bottom:12px">导入 {{importResult.total}} 条：成功 {{importResult.success_count}} 条，失败 {{importResult.failed_count}} 条。<ul v-if="importResult.failed_count"><li v-for="item in importResult.items.filter((x:any)=>x.status==='failed')" :key="item.line">第 {{item.line}} 行（{{item.equipment_code||'无设备编号'}}）：{{item.message}}</li></ul></n-alert>
    <n-data-table v-if="loading||rows.length" :columns="columns" :data="rows" :loading="loading" :pagination="{pageSize:12}" :scroll-x="1400"/>
    <div v-else class="empty-table-panel"><div class="onboarding-mark"><img src="/icons/factory.svg" alt=""></div><h4>尚未建立工程机械档案</h4><p>创建设备后可继续记录位置快照，并与施工区域及水害成果建立关联。</p><n-button type="primary" @click="newEquipment">新增工程机械</n-button></div>
  </n-card>

  <n-modal v-model:show="formVisible" preset="card" style="width:min(760px,92vw)" :title="form.id?'编辑工程机械':'新增工程机械'">
    <div class="form-grid"><n-select v-model:value="form.project_id" :options="activeProjectOptions" placeholder="所属施工项目" :disabled="!!form.id"/><n-input v-model:value="form.equipment_code" placeholder="设备编号，例如 EXC-001"/><n-input v-model:value="form.equipment_name" placeholder="设备名称"/><n-select v-model:value="form.equipment_type" :options="equipmentTypes"/><n-input v-model:value="form.manufacturer" placeholder="制造商（可选）"/><n-input v-model:value="form.model" placeholder="型号（可选）"/><n-select v-model:value="form.business_status" :options="businessStatuses"/><n-input v-model:value="form.description" type="textarea" placeholder="说明（可选）" class="wide"/></div><n-space justify="end"><n-button @click="formVisible=false">取消</n-button><n-button type="primary" :loading="saving" @click="saveEquipment">保存</n-button></n-space>
  </n-modal>

  <n-modal v-model:show="positionVisible" preset="card" style="width:min(680px,92vw)" title="记录设备位置快照">
    <n-alert type="warning" style="margin-bottom:14px">请填写位置对应的空间参考与实际记录时间；系统不会将该记录包装为实时定位。</n-alert>
    <div class="form-grid"><n-input-number v-model:value="positionForm.x" placeholder="X / 经度" style="width:100%"/><n-input-number v-model:value="positionForm.y" placeholder="Y / 纬度" style="width:100%"/><n-input v-model:value="positionForm.crs" placeholder="例如 EPSG:4326"/><n-date-picker v-model:value="positionForm.recordedAt" type="datetime" clearable style="width:100%"/><n-input v-model:value="positionForm.accuracy_note" placeholder="精度说明（可选）"/><n-input v-model:value="positionForm.source_note" placeholder="来源说明（可选）"/></div><n-space justify="end"><n-button @click="positionVisible=false">取消</n-button><n-button type="primary" :loading="saving" @click="savePosition">保存位置快照</n-button></n-space>
  </n-modal>

  <n-modal v-model:show="detailVisible" preset="card" style="width:min(1050px,94vw)" title="工程机械详情">
    <template v-if="detail"><n-descriptions bordered :column="3"><n-descriptions-item label="设备">{{detail.equipment_code}} · {{detail.equipment_name}}</n-descriptions-item><n-descriptions-item label="类型">{{detail.equipment_type_label}}</n-descriptions-item><n-descriptions-item label="所属项目">{{detail.project_name}}</n-descriptions-item><n-descriptions-item label="业务状态">{{detail.business_status_label}}</n-descriptions-item><n-descriptions-item label="制造商 / 型号">{{detail.manufacturer||'--'}} / {{detail.model||'--'}}</n-descriptions-item><n-descriptions-item label="档案状态">{{detail.lifecycle_status==='active'?'启用':'已归档'}}</n-descriptions-item></n-descriptions>
      <h4>最近位置与水害关联</h4><div v-if="detail.latest_position" class="snapshot-grid"><div><span>位置坐标</span><b>{{detail.latest_position.x}}, {{detail.latest_position.y}}</b></div><div><span>空间参考</span><b>{{detail.latest_position.crs}}</b></div><div><span>位置来源</span><b>{{detail.latest_position.position_source_label}}</b></div><div><span>位置时间</span><b>{{fmt(detail.latest_position.recorded_at)}}</b></div><div><span>所在施工区域</span><b>{{detail.current_work_areas?.map(x=>x.area_name).join('、')||'未落入所属项目已配置区域'}}</b></div><div><span>最近点位水害类别</span><b>{{detail.latest_risk_link?.risk_label||'暂无关联分析'}}</b></div></div><n-empty v-else description="暂无位置记录"/>
      <h4>位置地形辅助信息</h4><div class="terrain-tools"><n-select v-model:value="terrainDemId" :options="terrainOptions" placeholder="选择项目DEM"/><n-button type="primary" :disabled="!terrainDemId||!detail.latest_position" :loading="terrainRunning" @click="runTerrain">分析最近位置地形</n-button><n-button v-if="terrainSnapshots.length" tag="a" :href="api.equipmentTerrainCsvUrl(detail.id)" download>导出CSV</n-button></div><n-data-table v-if="terrainSnapshots.length" :columns="terrainColumns" :data="terrainSnapshots" :pagination="false"/><n-empty v-else description="暂无设备位置地形分析"/><p class="muted">相对低高程是DEM内部相对位置，不表示高风险、必然积水或机械不可通行。</p>
      <h4>所属项目近期降雨背景</h4><n-descriptions v-if="rainOverview?.has_data" bordered :column="4" size="small"><n-descriptions-item label="最近24小时">{{rain(rainOverview.rainfall_24h_mm)}}</n-descriptions-item><n-descriptions-item label="最近72小时">{{rain(rainOverview.rainfall_72h_mm)}}</n-descriptions-item><n-descriptions-item label="最近7天">{{rain(rainOverview.rainfall_7d_mm)}}</n-descriptions-item><n-descriptions-item label="最近观测">{{fmt(rainOverview.latest_observation_at)}}</n-descriptions-item></n-descriptions><n-empty v-else description="暂无所属项目降雨观测数据"/><p class="muted">项目降雨背景不代表该设备点位实际降雨，也不改变设备正式水害关联类别。</p>
      <h4>所在施工区域无人机影像</h4><n-alert v-if="uavAreaNames.length" type="info">所在施工区域存在可用无人机正射影像：{{uavAreaNames.join('、')}}。<n-button text type="primary" @click="$router.push('/areas')">前往施工区域查看</n-button></n-alert><n-empty v-else description="最近位置所在施工区域暂无已分析的无人机影像覆盖"/><p class="muted">这仅表示区域存在历史正射影像，不表示无人机正在监控设备，也不代表设备风险。</p>
      <h4>位置记录</h4><n-data-table v-if="detail.positions?.length" :columns="positionColumns" :data="detail.positions" :pagination="{pageSize:6}"/><n-empty v-else description="暂无位置记录"/>
      <h4>历史水害关联</h4><n-data-table v-if="detail.risk_links?.length" :columns="linkColumns" :data="detail.risk_links" :pagination="{pageSize:6}" :scroll-x="1000"/><n-empty v-else description="暂无设备水害关联记录"/>
      <n-alert type="warning" style="margin-top:14px">设备点位水害类别仅反映最近位置快照对应的遥感水害关注类别，不代表车辆安全状态或可通行性。</n-alert>
    </template>
  </n-modal>
  <n-card v-if="detail?.assistance_records" class="linked-assistance" title="当前设备作业辅助记录"><n-data-table v-if="detail.assistance_records.length" :columns="[{title:'事项名称',key:'title'},{title:'类型',key:'assistance_type_label'},{title:'优先级',key:'priority_label'},{title:'状态',key:'status_label'},{title:'生成时间',render:(r:any)=>fmt(r.created_at)}]" :data="detail.assistance_records" :pagination="false"/><n-empty v-else description="暂无与该设备关联的作业辅助事项"/><p v-if="detail.latest_assistance_verification" class="muted">最近人工核验：{{fmt(detail.latest_assistance_verification.verified_at)}} · {{detail.latest_assistance_verification.verification_result_label}}</p><p class="muted">关联依据设备最近位置快照，不代表实时设备状态。</p></n-card>
</template>

<script setup lang="ts">
import{computed,h,onMounted,ref,watch}from'vue'
import{NButton,NPopconfirm,NTag,useMessage}from'naive-ui'
import{api}from'../api'
import type{ConstructionEquipment,ConstructionProject,EquipmentPosition,EquipmentRiskLink,EquipmentTerrainSnapshot,RainfallOverview,TerrainDataset}from'../types'
import{formatDateTime}from'../utils/format'
import{currentProjectId}from'../composables/projectContext'
const msg=useMessage(),projects=ref<ConstructionProject[]>([]),rows=ref<ConstructionEquipment[]>([]),dems=ref<TerrainDataset[]>([]),terrainSnapshots=ref<EquipmentTerrainSnapshot[]>([]),rainOverview=ref<RainfallOverview|null>(null),uavAreaNames=ref<string[]>([]),terrainDemId=ref<string|null>(null),terrainRunning=ref(false),projectId=ref<string|null>(null),importResult=ref<any>(null),loading=ref(false),saving=ref(false),formVisible=ref(false),positionVisible=ref(false),detailVisible=ref(false),detail=ref<ConstructionEquipment|null>(null),positionTarget=ref<ConstructionEquipment|null>(null)
const equipmentTypes=[{label:'挖掘机',value:'excavator'},{label:'装载机',value:'loader'},{label:'自卸车',value:'dump_truck'},{label:'矿卡',value:'mining_truck'},{label:'推土机',value:'bulldozer'},{label:'压路机',value:'roller'},{label:'起重机',value:'crane'},{label:'其他',value:'other'}]
const businessStatuses=[{label:'待命',value:'idle'},{label:'作业中',value:'working'},{label:'暂停作业',value:'paused'},{label:'维护',value:'maintenance'},{label:'离线/未更新',value:'offline'}]
const projectOptions=computed(()=>projects.value.map(x=>({label:`${x.project_name} · ${x.project_code}`,value:x.id}))),activeProjectOptions=computed(()=>projects.value.filter(x=>x.status==='active').map(x=>({label:`${x.project_name} · ${x.project_code}`,value:x.id})))
const terrainOptions=computed(()=>dems.value.filter(x=>!x.project_id||x.project_id===detail.value?.project_id).map(x=>({label:`${x.name} · ${x.crs}`,value:x.id})))
const form=ref({id:'',project_id:'',equipment_code:'',equipment_name:'',equipment_type:'excavator',manufacturer:'',model:'',business_status:'idle',description:''}),positionForm=ref<{x:number|null;y:number|null;crs:string;recordedAt:number|null;accuracy_note:string;source_note:string}>({x:null,y:null,crs:'EPSG:4326',recordedAt:Date.now(),accuracy_note:'',source_note:''})
const fmt=(v:string|null|undefined)=>v?formatDateTime(v):'--',age=(v:number)=>`${v.toFixed(1)} 小时`,riskType=(v?:string)=>v==='HIGH_ATTENTION_AREA'?'error':v==='INSPECTION_AREA'?'warning':v==='GENERAL_WATER_AREA'?'success':'default'
const rain=(v:number|null)=>v==null?'无数据':`${v.toFixed(2)} mm`
async function loadEquipment(){loading.value=true;try{rows.value=await api.equipment(projectId.value||undefined)}catch(e:any){msg.error(e.message)}finally{loading.value=false}}
function newEquipment(){form.value={id:'',project_id:projectId.value||'',equipment_code:'',equipment_name:'',equipment_type:'excavator',manufacturer:'',model:'',business_status:'idle',description:''};formVisible.value=true}
function editEquipment(row:ConstructionEquipment){form.value={id:row.id,project_id:row.project_id,equipment_code:row.equipment_code,equipment_name:row.equipment_name,equipment_type:row.equipment_type,manufacturer:row.manufacturer,model:row.model,business_status:row.business_status,description:row.description};formVisible.value=true}
async function saveEquipment(){const f=form.value;if(!f.project_id||!f.equipment_code.trim()||!f.equipment_name.trim()){msg.warning('请填写所属项目、设备编号和设备名称');return}saving.value=true;try{const payload={project_id:f.project_id,equipment_code:f.equipment_code.trim(),equipment_name:f.equipment_name.trim(),equipment_type:f.equipment_type,manufacturer:f.manufacturer.trim(),model:f.model.trim(),business_status:f.business_status,description:f.description.trim()};f.id?await api.updateEquipment(f.id,payload):await api.createEquipment(payload);formVisible.value=false;await loadEquipment();msg.success('工程机械已保存')}catch(e:any){msg.error(e.message)}finally{saving.value=false}}
function addPosition(row:ConstructionEquipment){positionTarget.value=row;positionForm.value={x:null,y:null,crs:'EPSG:4326',recordedAt:Date.now(),accuracy_note:'',source_note:''};positionVisible.value=true}
async function savePosition(){if(!positionTarget.value||positionForm.value.x==null||positionForm.value.y==null||!positionForm.value.recordedAt){msg.warning('请填写坐标和位置时间');return}saving.value=true;try{await api.addEquipmentPosition(positionTarget.value.id,{x:positionForm.value.x,y:positionForm.value.y,crs:positionForm.value.crs,recorded_at:new Date(positionForm.value.recordedAt).toISOString(),accuracy_note:positionForm.value.accuracy_note,source_note:positionForm.value.source_note});positionVisible.value=false;await loadEquipment();msg.success('位置快照已保存')}catch(e:any){msg.error(e.message)}finally{saving.value=false}}
async function openDetail(row:ConstructionEquipment){try{[detail.value,terrainSnapshots.value,rainOverview.value]=await Promise.all([api.equipmentDetail(row.id),api.equipmentTerrain(row.id),api.rainfallOverview(row.project_id)]);const areaRows=detail.value.current_work_areas||[];const coverages=await Promise.all(areaRows.map(x=>api.areaUavCoverages(x.id)));uavAreaNames.value=areaRows.filter((_,i)=>coverages[i].some(c=>c.coverage_ratio>0)).map(x=>x.area_name);terrainDemId.value=terrainSnapshots.value[0]?.dem_id||null;detailVisible.value=true}catch(e:any){msg.error(e.message)}}
async function runTerrain(){if(!detail.value||!terrainDemId.value)return;terrainRunning.value=true;try{await api.runEquipmentTerrain(detail.value.id,terrainDemId.value);terrainSnapshots.value=await api.equipmentTerrain(detail.value.id);msg.success('设备最近位置地形分析已完成')}catch(e:any){msg.error(e.message)}finally{terrainRunning.value=false}}
async function archive(row:ConstructionEquipment){try{await api.updateEquipment(row.id,{lifecycle_status:'archived'});await loadEquipment();msg.success('设备已归档，历史记录已保留')}catch(e:any){msg.error(e.message)}}
async function remove(row:ConstructionEquipment){try{await api.removeEquipment(row.id);await loadEquipment();msg.success('无历史记录设备已删除')}catch(e:any){msg.error(e.message)}}
async function importCsv(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const result=await api.importEquipmentPositions(file);importResult.value=result;result.failed_count?msg.warning(`导入完成：成功 ${result.success_count} 条，失败 ${result.failed_count} 条`):msg.success(`成功导入 ${result.success_count} 条位置快照`);await loadEquipment()}catch(e:any){msg.error(e.message)}finally{input.value=''}}
const columns=[{title:'设备编号',key:'equipment_code',width:120},{title:'设备名称',key:'equipment_name',width:160},{title:'类型',key:'equipment_type_label',width:100},{title:'所属项目',key:'project_name',width:170},{title:'业务状态',render:(r:ConstructionEquipment)=>h(NTag,{type:r.business_status==='working'?'success':r.business_status==='maintenance'?'warning':'default'},{default:()=>r.business_status_label}),width:110},{title:'最近位置时间',render:(r:ConstructionEquipment)=>fmt(r.latest_position?.recorded_at),width:160},{title:'位置来源',render:(r:ConstructionEquipment)=>r.latest_position?.position_source_label||'暂无位置',width:100},{title:'点位水害类别',render:(r:ConstructionEquipment)=>h(NTag,{type:riskType(r.latest_risk_link?.risk_class)},{default:()=>r.latest_risk_link?.risk_label||'暂无关联'}),width:140},{title:'所在施工区域',render:(r:ConstructionEquipment)=>r.latest_risk_link?.work_area_names?.join('、')||'--',width:180,ellipsis:{tooltip:true}},{title:'位置时效',render:(r:ConstructionEquipment)=>r.latest_risk_link?(r.latest_risk_link.position_status==='stale'?'位置已过期':'位置有效'):'--',width:105},{title:'操作',fixed:'right' as const,width:255,render:(r:ConstructionEquipment)=>h('div',{style:'display:flex;gap:5px'},[h(NButton,{size:'small',onClick:()=>openDetail(r)},{default:()=>'详情'}),h(NButton,{size:'small',disabled:r.lifecycle_status!=='active',onClick:()=>addPosition(r)},{default:()=>'录入位置'}),h(NButton,{size:'small',onClick:()=>editEquipment(r)},{default:()=>'编辑'}),r.lifecycle_status==='active'&&h(NButton,{size:'small',onClick:()=>archive(r)},{default:()=>'归档'}),h(NPopconfirm,{onPositiveClick:()=>remove(r)},{trigger:()=>h(NButton,{size:'small',type:'error',secondary:true},{default:()=>'删除'}),default:()=>'仅无位置及水害关联历史的设备可删除。'})])}]
const positionColumns=[{title:'记录时间',render:(r:EquipmentPosition)=>fmt(r.recorded_at)},{title:'坐标',render:(r:EquipmentPosition)=>`${r.x}, ${r.y}`},{title:'CRS',key:'crs'},{title:'来源',key:'position_source_label'},{title:'当前记录年龄',render:(r:EquipmentPosition)=>age(r.position_age_hours)}]
const linkColumns=[{title:'关联时间',render:(r:EquipmentRiskLink)=>fmt(r.created_at),width:160},{title:'位置时间',render:(r:EquipmentRiskLink)=>fmt(r.recorded_at),width:160},{title:'点位水害类别',key:'risk_label',width:150},{title:'所在区域',render:(r:EquipmentRiskLink)=>r.work_area_names.join('、')||'未命中',width:180},{title:'区域影响',render:(r:EquipmentRiskLink)=>r.work_area_impact_level||'--',width:120},{title:'位置状态',render:(r:EquipmentRiskLink)=>r.position_status==='stale'?'位置已过期':'位置有效',width:110},{title:'提示',key:'advice_text',width:280,ellipsis:{tooltip:true}}]
const terrainColumns=[{title:'DEM',key:'dem_name'},{title:'状态',render:(r:EquipmentTerrainSnapshot)=>r.status==='completed'?'有效':r.status==='outside_extent'?'超出范围':'无有效数据'},{title:'高程',render:(r:EquipmentTerrainSnapshot)=>r.elevation==null?'--':`${r.elevation.toFixed(2)} m`},{title:'坡度',render:(r:EquipmentTerrainSnapshot)=>r.slope==null?'--':`${r.slope.toFixed(2)}°`},{title:'相对低高程',render:(r:EquipmentTerrainSnapshot)=>r.is_low_elevation==null?'--':r.is_low_elevation?'是':'否'},{title:'分析时间',render:(r:EquipmentTerrainSnapshot)=>fmt(r.created_at)},{title:'说明',key:'terrain_note',ellipsis:{tooltip:true}}]
watch(currentProjectId,value=>{projectId.value=value;void loadEquipment()});onMounted(async()=>{try{[projects.value,dems.value]=await Promise.all([api.projects(),api.demDatasets()]);projectId.value=currentProjectId.value;await loadEquipment()}catch(e:any){msg.error(e.message)}})
</script>

<style scoped>.table-actions{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;color:#8795a3}.csv-button{padding:7px 14px;border:1px solid rgba(100,145,165,.4);border-radius:5px;cursor:pointer;color:inherit}.csv-button input{display:none}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px}.wide{grid-column:1/-1}.snapshot-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.snapshot-grid div{display:flex;flex-direction:column;gap:5px;padding:12px;background:rgba(100,145,165,.08)}.snapshot-grid span{font-size:12px;color:#8795a3}.snapshot-grid b{font-size:13px}.terrain-tools{display:grid;grid-template-columns:1fr auto auto;gap:10px;margin-bottom:12px}@media(max-width:800px){.form-grid,.snapshot-grid,.terrain-tools{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
